using System.Data;using Backend.BDFolder;using Backend.Exceptions;using Backend.Helpers;using Backend.Models;using Backend.Policies;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using Polly;namespace Backend.Services;public class RolService{    private readonly IDbContextFactory<TransportesRojasDbContext> _factory;    private readonly ILogger<RolService> _logger;    private readonly ResiliencePipeline _pipeline;    public RolService(        IDbContextFactory<TransportesRojasDbContext> factory,        ILogger<RolService> logger)    {        _factory = factory;        _logger = logger;        _pipeline = PollyPolicies.CrearPipelineSerializacion(logger);    }    public async Task<List<RolResponse>> GetRolesAsync(int skip = 0, int take = 100)    {        await using var ctx = await _factory.CreateDbContextAsync();        return await ctx.Roles            .AsNoTracking()            .OrderBy(r => r.Id)            .Skip(skip)            .Take(take)            .Select(r => new RolResponse(r.Id, r.Nombre, r.Descripcion))            .ToListAsync();    }    public async Task<RolResponse?> GetRolByIdAsync(long id)    {        await using var ctx = await _factory.CreateDbContextAsync();        var rol = await ctx.Roles            .AsNoTracking()            .FirstOrDefaultAsync(r => r.Id == id);        return rol is null            ? null            : new RolResponse(rol.Id, rol.Nombre, rol.Descripcion);    }    public async Task<RolResponse> CreateRolAsync(CrearRolModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var existeNombre = await ctx.Roles                    .AnyAsync(r => r.Nombre == model.Nombre, ct);                if (existeNombre)                    throw new InvalidOperationException(                        $"Ya existe un rol con el nombre '{model.Nombre}'.");                var nuevoRol = new Rol                {                    Nombre = model.Nombre,                    Descripcion = model.Descripcion                };                ctx.Roles.Add(nuevoRol);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Rol creado exitosamente. Id={RolId}, Nombre='{Nombre}'",                    nuevoRol.Id, nuevoRol.Nombre);                return new RolResponse(nuevoRol.Id, nuevoRol.Nombre, nuevoRol.Descripcion);            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException(                    "Conflicto de serialización al crear rol.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> UpdateRolAsync(long id, ActualizarRolModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var rol = await ctx.Roles.FindAsync(new object[] { id }, ct);                if (rol is null)                    return false;                var existeNombre = await ctx.Roles                    .AnyAsync(r => r.Nombre == model.Nombre && r.Id != id, ct);                if (existeNombre)                    throw new InvalidOperationException(                        $"Ya existe otro rol con el nombre '{model.Nombre}'.");                rol.Nombre = model.Nombre;                rol.Descripcion = model.Descripcion;                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Rol actualizado exitosamente. Id={RolId}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException(                    "Conflicto de serialización al actualizar rol.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> DeleteRolAsync(long id)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var rol = await ctx.Roles.FindAsync(new object[] { id }, ct);                if (rol is null)                    return false;                var estaEnUso = await ctx.UsuarioRoles                    .AnyAsync(ur => ur.RolId == id, ct);                if (estaEnUso)                    throw new InvalidOperationException(                        "No se puede eliminar el rol porque está asignado a uno o más usuarios.");                ctx.Roles.Remove(rol);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Rol eliminado exitosamente. Id={RolId}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException(                    "Conflicto de serialización al eliminar rol.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    private async Task RollbackSafeAsync(        Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction tx)    {        try        {            await tx.RollbackAsync();        }        catch (Exception rollbackEx)        {            _logger.LogWarning(rollbackEx,                "Error durante el rollback de la transacción (puede ser esperado si la conexión ya se cerró).");        }    }}